import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int a = sc.nextInt();
        int l = sc.nextInt();
        int n = sc.nextInt();

        int photoMin = Math.min(a, l);
        int photoMax = Math.max(a, l);

        int bestIndex = -1;
        long bestArea = Long.MAX_VALUE;

        for (int i = 1; i <= n; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();

            int frameMin = Math.min(x, y);
            int frameMax = Math.max(x, y);

            if (photoMin <= frameMin && photoMax <= frameMax) {
                long area = (long) x * y;
                if (area < bestArea) {
                    bestArea = area;
                    bestIndex = i;
                }
            }
        }

        System.out.println(bestIndex);
    }
}
